starter_code:
define :queen [
    init: constructor [row column]

    attackable?: method [other] [
        panic "Please implement the attackable? method"
    ]
]

example_solution:
define :queen [
    init: constructor [row :integer column :integer]

    attackable?: method [other] [
        any? @[
            this\row = other\row
            this\column = other\column
            (abs this\row - other\row) = (abs this\column - other\column)
        ]
    ]
]
